// SPDX-License-Identifier: MIT
pragma solidity ^0.8.0;

/// @title  ISafe
/// @author KPK
/// @notice Minimal interface for a Gnosis Safe proxy (v1.4.1).
/// @dev    Only the functions used by KpkOivFactory are included.
interface ISafe {
    /// @notice One-time initializer called by SafeProxyFactory immediately after proxy creation.
    /// @dev    Must be called exactly once. `to` and `data` form an optional delegatecall
    ///         executed during setup (e.g. SafeModuleSetup.enableModules).
    /// @param _owners          Initial set of owner accounts.
    /// @param _threshold       Number of owner signatures required to execute a transaction.
    /// @param to               Delegatecall target executed during setup, or address(0) to skip.
    /// @param data             Calldata for the delegatecall, or empty bytes to skip.
    /// @param fallbackHandler  Contract to handle ERC-165 / ERC-1271 fallback calls.
    /// @param paymentToken     Token used to reimburse the relayer, or address(0) for ETH.
    /// @param payment          Amount paid to the relayer, or 0 for none.
    /// @param paymentReceiver  Recipient of the relayer payment, or address(0) for msg.sender.
    function setup(
        address[] calldata _owners,
        uint256 _threshold,
        address to,
        bytes calldata data,
        address fallbackHandler,
        address paymentToken,
        uint256 payment,
        address payable paymentReceiver
    ) external;

    /// @notice Returns whether `module` is currently enabled on this Safe.
    /// @param module  Address to check.
    /// @return        True if the module is in the enabled-modules linked list.
    function isModuleEnabled(address module) external view returns (bool);

    /// @notice Returns the current list of Safe owner addresses.
    function getOwners() external view returns (address[] memory);

    /// @notice Returns the current signature threshold.
    function getThreshold() external view returns (uint256);

    /// @notice Executes a call or delegatecall on behalf of this Safe without collecting signatures.
    /// @dev    Callable only by an enabled module.
    ///         `operation` 0 = CALL, 1 = DELEGATECALL.
    /// @param to        Destination address.
    /// @param value     ETH value to forward.
    /// @param data      Calldata to send.
    /// @param operation Operation type (0 = CALL, 1 = DELEGATECALL).
    /// @return success  Whether the inner call succeeded.
    function execTransactionFromModule(address to, uint256 value, bytes memory data, uint8 operation)
        external
        returns (bool success);

    /// @notice Removes `module` from the enabled-modules linked list.
    /// @dev    Callable only by the Safe itself (i.e. via an executed Safe transaction or module).
    ///         `prevModule` must be the entry that points to `module` in the linked list.
    ///         Pass `SENTINEL_MODULES` (0x0000...0001) as `prevModule` when `module` is the head.
    /// @param prevModule  The module that precedes `module` in the linked list.
    /// @param module      The module to disable.
    function disableModule(address prevModule, address module) external;
}

src/interfaces/ISafeProxyFactory.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.0;

/// @title  ISafeProxyFactory
/// @author KPK
/// @notice Minimal interface for the Gnosis SafeProxyFactory (v1.4.1).
/// @dev    Only the function used by KpkOivFactory is included.
interface ISafeProxyFactory {
    /// @notice Deploys a new Safe proxy that delegates to `_singleton` and executes the
    ///         provided `initializer` on the newly created proxy immediately after creation.
    /// @dev    CREATE2 salt = keccak256(abi.encodePacked(keccak256(initializer), saltNonce)).
    ///         The same `_singleton`, `initializer`, and `saltNonce` combination will always
    ///         produce the same proxy address on a given factory/chain.
    /// @param _singleton  The Safe implementation (singleton) the proxy delegates to.
    /// @param initializer ABI-encoded `ISafe.setup(...)` call executed on the new proxy.
    /// @param saltNonce   Unique nonce mixed into the CREATE2 salt for address derivation.
    /// @return proxy      Address of the newly deployed Safe proxy.
    function createProxyWithNonce(address _singleton, bytes memory initializer, uint256 saltNonce)
        external
        returns (address proxy);

    /// @notice Returns the creation bytecode of the SafeProxy contract.
    /// @dev    Used to compute deterministic CREATE2 addresses off-chain or via on-chain
    ///         prediction helpers without re-implementing SafeProxy creation code.
    function proxyCreationCode() external pure returns (bytes memory);
}

src/interfaces/ISafeModuleSetup.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.0;

/// @title  ISafeModuleSetup
/// @author KPK
/// @notice Delegatecall target used in Safe's setup() to enable modules during initialization.
/// @dev    Deployed at a deterministic address by Safe as part of their v1.4.1 contracts.
///         KpkOivFactory encodes a delegatecall to `enableModules` inside the Safe
///         `setup()` initializer so that modules are pre-enabled at proxy creation time,
///         avoiding the need for a post-deployment owner transaction.
interface ISafeModuleSetup {
    /// @notice Enables a list of modules on the Safe being initialized.
    /// @dev    Must be called via delegatecall from within Safe.setup(); calling it directly
    ///         has no effect because it writes to `msg.sender`'s (i.e. the Safe's) storage.
    ///         The modules are inserted into the linked list in reverse order:
    ///         `enableModules([A, B])` results in SENTINEL → B → A → SENTINEL.
    /// @param modules  Ordered list of module addresses to enable. Must be non-empty.
    function enableModules(address[] calldata modules) external;
}

