// SPDX-License-Identifier: MIT
pragma solidity ^0.8.0;

/// @title  IModuleProxyFactory
/// @author KPK
/// @notice Minimal interface for the Zodiac ModuleProxyFactory.
/// @dev    Deploys EIP-1167 minimal proxies for Zodiac modules (e.g. Roles Modifier) via CREATE2.
///         Only the function used by KpkOivFactory is included.
interface IModuleProxyFactory {
    /// @notice Deploys a new EIP-1167 minimal proxy pointing at `masterCopy` and calls
    ///         `masterCopy.setUp(initializer)` on the proxy immediately after creation.
    /// @dev    CREATE2 salt = keccak256(abi.encodePacked(keccak256(initializer), saltNonce)).
    ///         The same `masterCopy`, `initializer`, and `saltNonce` produce the same proxy
    ///         address on any chain, enabling deterministic cross-chain deployments.
    /// @param masterCopy  The Zodiac module implementation all proxies delegate to.
    /// @param initializer ABI-encoded `setUp(...)` call executed on the new proxy.
    /// @param saltNonce   Unique nonce mixed into the CREATE2 salt for address derivation.
    /// @return proxy      Address of the newly deployed module proxy.
    function deployModule(address masterCopy, bytes memory initializer, uint256 saltNonce)
        external
        returns (address proxy);
}

src/interfaces/IRoles.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.0;

/// @title  IRoles
/// @author KPK
/// @notice Minimal interface for the Zodiac Roles Modifier v2.
/// @dev    Only the functions used by KpkOivFactory (and its tests) are included.
///         setUp encodes (address owner, address avatar, address target).
///         enableModule requires msg.sender == avatar.
///         All other configuration functions require msg.sender == owner.
interface IRoles {
    /// @notice One-time initializer called by ModuleProxyFactory after proxy creation.
    /// @param initParams ABI-encoded (address owner, address avatar, address target).
    function setUp(bytes memory initParams) external;

    /// @notice Returns the avatar address — the Safe whose assets the modifier guards.
    function avatar() external view returns (address);

    /// @notice Returns the target address — the contract that executions are forwarded to.
    /// @dev    Usually equals avatar. For nested modifiers, this is the parent modifier.
    function target() external view returns (address);

    /// @notice Updates the avatar address.
    /// @dev    Callable only by the current owner.
    /// @param _avatar New avatar address.
    function setAvatar(address _avatar) external;

    /// @notice Updates the target address.
    /// @dev    Callable only by the current owner.
    /// @param _target New target address.
    function setTarget(address _target) external;

    /// @notice Returns the current owner of this Roles Modifier.
    function owner() external view returns (address);

    /// @notice Transfers ownership to `newOwner`.
    /// @dev    Callable only by the current owner.
    /// @param newOwner Address that will become the new owner.
    function transferOwnership(address newOwner) external;

    /// @notice Assigns or revokes roles for `module`.
    /// @dev    Callable only by the current owner.
    ///         `roleKeys` and `memberOf` must have the same length.
    /// @param module    Address whose role membership is being updated.
    /// @param roleKeys  Array of role identifiers.
    /// @param memberOf  Parallel array: true to grant, false to revoke.
    function assignRoles(address module, bytes32[] calldata roleKeys, bool[] calldata memberOf) external;

    /// @notice Sets the default role for `module`.
    /// @dev    Callable only by the current owner. The default role is used when
    ///         execTransactionWithRole is called without specifying a role.
    /// @param module   Address whose default role is being set.
    /// @param roleKey  Role to assign as the default.
    function setDefaultRole(address module, bytes32 roleKey) external;

    /// @notice Enables this modifier as a module on the avatar Safe.
    /// @dev    Callable only by the avatar (i.e. the Safe itself, or an enabled module of it).
    /// @param module Address to enable as a module.
    function enableModule(address module) external;

    /// @notice Returns whether `module` is enabled on this Roles Modifier.
    /// @param module Address to check.
    /// @return       True if the module is enabled.
    function isModuleEnabled(address module) external view returns (bool);

    /// @notice Marks `targetAddress` as a scoped target for `roleKey`.
    /// @dev    Callable only by the current owner. Functions must be allowed via
    ///         allowFunction before they can be called by role holders.
    /// @param roleKey       Role to configure.
    /// @param targetAddress Contract address to scope.
    function scopeTarget(bytes32 roleKey, address targetAddress) external;

    /// @notice Allows `selector` on `targetAddress` for `roleKey`.
    /// @dev    Callable only by the current owner.
    ///         `options` controls additional execution constraints (e.g. value allowed).
    /// @param roleKey       Role to configure.
    /// @param targetAddress Contract address where the function lives.
    /// @param selector      4-byte function selector to allow.
    /// @param options       Execution options bitmask (0 = none, 1 = send, 2 = delegatecall, 3 = both).
    function allowFunction(bytes32 roleKey, address targetAddress, bytes4 selector, uint8 options) external;

    /// @notice Registers (or clears) the unwrap adapter used to decompose calls to
    ///         `to.selector` before permission-checking them.
    /// @dev    Callable only by the current owner. Without an adapter a batched
    ///         `multiSend(bytes)` delegatecall is one opaque blob the modifier cannot
    ///         permission-check, so it is rejected wholesale. The adapter is keyed on the
    ///         `(to, selector)` pair, so each MultiSend variant must be registered separately.
    ///         Pass `address(0)` as `adapter` to remove a registration.
    /// @param to       Target contract whose calls need unwrapping (a MultiSend contract).
    /// @param selector 4-byte selector on `to` that carries the batch (`multiSend(bytes)`).
    /// @param adapter  Unwrap adapter implementing Zodiac's `ITransactionUnwrapper`.
    function setTransactionUnwrapper(address to, bytes4 selector, address adapter) external;

    /// @notice Returns the unwrap adapter registered for a `(to, selector)` pair.
    /// @dev    `key` packs the target into the high 20 bytes, the selector into the next 4, and
    ///         leaves the low 8 bytes zero:
    ///
    ///             bytes0..19  = to
    ///             bytes20..23 = selector
    ///             bytes24..31 = 0
    ///
    ///         In Solidity that is `bytes32(bytes20(to)) | (bytes32(selector) >> 160)`.
    ///         (`abi.encodePacked(to, selector)` produces the same 24 bytes but returns `bytes`,
    ///         which has no direct conversion to `bytes32` — use the shift form above.)
    /// @param key Packed `(to, selector)` key.
    /// @return    Registered adapter, or the zero address when none is set.
    function unwrappers(bytes32 key) external view returns (address);

    /// @notice Executes a transaction through the modifier if the caller holds `roleKey`.
    /// @dev    Forwards the call to target if all role checks pass.
    ///         If `shouldRevert` is true the call reverts on inner failure; otherwise it returns false.
    /// @param to           Destination address.
    /// @param value        ETH value to forward.
    /// @param data         Calldata to send.
    /// @param operation    0 = CALL, 1 = DELEGATECALL.
    /// @param roleKey      Role the caller must hold.
    /// @param shouldRevert Whether to revert on failure rather than returning false.
    /// @return success     Whether the inner execution succeeded.
    function execTransactionWithRole(
        address to,
        uint256 value,
        bytes calldata data,
        uint8 operation,
        bytes32 roleKey,
        bool shouldRevert
    ) external returns (bool success);
}

src/OivInfraConstants.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.0;

/// @title  OivInfraConstants
/// @notice Single source of truth for the canonical, same-on-every-chain infra addresses that the
///         OIV deploy path bakes into CREATE2 init-code and that the test suites fork against.
/// @dev    Both `script/base/OivChainDeploy.sol` (the deploy path) and the test suites reference
///         these constants so a value can never drift between what actually deploys and what the
///         tests validate. Before this library the Roles Modifier mastercopy in particular was a
///         hand-maintained literal in five places, so a single version bump had to touch each by
///         hand and a miss would silently validate against a stale mastercopy.
///
///         NOTE: `script/ccip-networks.json` keeps its own copy of these (its `.infra` block) for
///         operator reference. It is a data file, not Solidity, but it is cross-checked against this
///         library by `test/CcipNetworksSync.t.sol::test_infraAddressesMatchLibrary`, so a one-sided
///         edit (bumping a value here without the JSON, or vice versa) fails CI rather than silently
///         drifting. Update both when changing a value.
library OivInfraConstants {
    // ── Safe v1.4.1 ─────────────────────────────────────────────────────────────
    address internal constant SAFE_PROXY_FACTORY = 0xa6B71E26C5e0845f74c812102Ca7114b6a896AB2;
    address internal constant SAFE_SINGLETON = 0x41675C099F32341bf84BFc5382aF534df5C7461a;
    address internal constant SAFE_MODULE_SETUP = 0x2dd68b007B46fBe91B9A7c3EDa5A7a1063cB5b47;
    address internal constant SAFE_FALLBACK_HANDLER = 0xfd0732Dc9E303f09fCEf3a7388Ad10A83459Ec99;

    // ── Zodiac ──────────────────────────────────────────────────────────────────
